<script setup lang="ts">definePageMeta({layout:"default"});useSeoMeta({title:"کسب‌وکار من | هفت‌سو",robots:"noindex,nofollow"});const{businesses,dashboard,load,message,pending}=useBusiness();onMounted(load);</script><template><AccountShell title="کسب‌وکار من" description="فروشگاه، اعضای تیم، شعب و عملکرد آگهی‌ها را یکجا مدیریت کنید."><template #action><NuxtLink class="button button--primary" to="/my/business/team">مدیریت تیم</NuxtLink></template><UiState v-if="pending" kind="loading" title="در حال دریافت حساب کسب‌وکار" description="اطلاعات تیم و عملکرد فروشگاه در حال همگام‌سازی است."/><template v-else><section v-for="business in businesses" :key="business.id" class="business-summary-card"><div><p class="eyebrow">{{business.verification_state==='verified'?'کسب‌وکار تأییدشده':'نیازمند احراز'}}</p><h2>{{business.display_name}}</h2><p>{{business.member_count}} عضو · {{business.listing_count}} آگهی</p></div><NuxtLink :to="`/store/${business.slug}`" class="button button--secondary">مشاهده فروشگاه</NuxtLink></section><BusinessMetricCards :data="dashboard"/><p v-if="message" role="status">{{message}}</p></template></AccountShell></template>
